INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 8, 'theory', 'Квиз: Docker для администратора');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 8, 0, 'Что верно про контейнер Docker на хосте с Linux?', '["Внутри работает отдельное ядро Linux", "Это виртуальная машина с облегчённым гипервизором", "Это обычный процесс хоста в своих пространствах имён и группе ресурсов", "Он не виден в списке процессов хоста"]', 2, 'Контейнеры и хост работают на одном ядре. Процесс контейнера виден на хосте обычным ps, а изоляцию дают пространства имён, группа ресурсов, урезанные права и фильтры системных вызовов.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 8, 1, 'Контейнер запущен с --memory 512m --memory-swap 768m на cgroup v2. Какие значения будут в файлах?', '["memory.max 536870912, memory.swap.max 268435456", "memory.max 536870912, memory.swap.max 805306368", "memory.max 805306368, memory.swap.max 268435456", "memory.max 536870912, memory.swap.max 768"]', 0, 'Флаг --memory-swap задаёт сумму памяти и подкачки: 768 МиБ всего. Память 512 МиБ, поэтому подкачке остаётся 768 минус 512, то есть 256 МиБ, или 268435456 байт.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 8, 2, 'В строке mount указано lowerdir=l/AAA:l/BBB:l/CCC. Какой слой образа верхний?', '["CCC: последний в списке", "BBB: средний слой", "Верхнего слоя нет, все слои равноправны", "AAA: первый в списке"]', 3, 'В lowerdir слои перечислены слева направо сверху вниз: самый левый верхний, самый правый основа образа. Поверх всех лежит записываемый upperdir.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 8, 3, 'Контейнер вышел с кодом 137, а в docker inspect флаг OOMKilled равен false. Что наиболее вероятно?', '["Программа завершилась штатно с кодом 137", "Процесс убит сигналом SIGKILL не из-за лимита памяти контейнера, например docker stop или docker kill", "Docker не смог запустить команду", "Контейнер вышел из-за ошибки сегментации"]', 1, '137 это 128 плюс сигнал 9. Нехватку памяти внутри лимита контейнера отмечает OOMKilled=true; здесь, скорее всего, kill после stop или ручной kill. Если хост в целом без памяти, проверьте dmesg.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 8, 4, 'Что означает запуск контейнера с -v /var/run/docker.sock:/var/run/docker.sock?', '["Контейнер получает доступ только к журналу демона", "Контейнер сможет только читать список образов", "Контейнер управляет демоном, а значит фактически имеет root на хосте", "Ничего особенного: сокет доступен всем контейнерам и так"]', 2, 'Через сокет можно запустить новый контейнер с корнем хоста внутри. Поэтому доступ к демону равен root на хосте, и такой контейнер нельзя считать изолированным.');
